files['src/mocks/bomData.js']=r'''import {mockFacilities} from '@/mocks/facilities';
import {managerSeed,assignedFacility} from '@/mocks/managerData';
export const bomToday=new Date().toLocaleDateString('en-CA');
export const bomServices=['SELF_STORAGE','MANAGED_INVENTORY'];
export const bomPolicyTypes=['Deposit','Cancellation','Refund','Overdue','Grace period','Access suspension','Forced termination'];
// Demo permissions only. Real BOM role/audit authorization contracts are unconfirmed.
export const bomDemoPermissions={manageBusiness:true,viewAudit:true};
const clone=x=>JSON.parse(JSON.stringify(x));
const facilities=mockFacilities.map((f,i)=>({...f,status:i===2?'INACTIVE':f.status}));
const rows={customers:[],units:[],rentals:[],payments:[],capacitySnapshots:[],alerts:[],contractSnapshots:[]};
for(const [index,f] of facilities.entries()){
 const prefix=index?'B'+(index+1)+'-':'';const id=x=>x?prefix+x:x;
 rows.customers.push(...clone(managerSeed.customers).map(x=>({...x,id:id(x.id),facilityId:f.id})));
 rows.units.push(...clone(managerSeed.units).map(x=>({...x,id:id(x.id),rentalId:id(x.rentalId),facilityId:f.id})));
 const rentals=clone(managerSeed.rentals).map(x=>({...x,id:id(x.id),customerId:id(x.customerId),unitId:id(x.unitId),facilityId:f.id,...(x.service==='MANAGED_INVENTORY'?{allocated_capacity_m3:[10,12,8][index],used_capacity_m3:[4,6,2][index],monthly:[2000000,2400000,1600000][index]}:{})}));rows.rentals.push(...rentals);
 rows.payments.push(...clone(managerSeed.payments).map(x=>({...x,id:id(x.id),customerId:id(x.customerId),rentalId:id(x.rentalId),facilityId:f.id})));
 rows.capacitySnapshots.push({id:'CAP-'+f.id,facilityId:f.id,operational_capacity_m3:managerSeed.shelves.filter(s=>s.status==='ACTIVE').reduce((sum,s)=>sum+s.max_volume_m3,0),asOf:bomToday});
 rows.alerts.push(...managerSeed.maintenance.filter(m=>m.status!=='RESOLVED').map(m=>({id:id(m.id),facilityId:f.id,service:m.resourceType==='Storage Unit'?'SELF_STORAGE':'MANAGED_INVENTORY',status:m.status,priority:m.priority,message:m.issue,date:bomToday})),...rentals.filter(r=>r.status==='OVERDUE').map(r=>({id:'ALERT-'+r.id,facilityId:f.id,service:r.service,status:'OVERDUE',priority:'HIGH',message:r.id+' checkout/payment review pending',date:r.end})));
 rows.contractSnapshots.push(...rentals.map(r=>({id:'SNAP-'+r.id,rentalId:r.id,facilityId:f.id,service:r.service,monthly:r.monthly,unitId:r.unitId||null,allocated_capacity_m3:r.allocated_capacity_m3||null,captured:r.start,description:'Read-only historical demo pricing snapshot'})));
}
const effective=bomToday;
export const bomSeed={facilities,...rows,
 facilityManagers:facilities.map((f,i)=>({id:'MGR-'+f.id,facilityId:f.id,name:i===0?assignedFacility.manager:'Not confirmed in demo source'})),
 facilityRules:facilities.map(f=>({id:'RULES-'+f.id,facilityId:f.id,description:'Demo: follow the site opening hours; reservations require an active facility. Existing rentals continue when a facility is deactivated.'})),
 pricing:[...['Small','Medium','Large'].map(size=>({id:'BPRICE-'+size.toUpperCase(),name:size+' private unit monthly price',facilityId:'ALL',service:'SELF_STORAGE',unitSize:size,billingMonths:1,rate:managerSeed.units.find(u=>u.size===size).price,effectiveFrom:effective,effectiveTo:'',status:'ACTIVE',revision:1,updatedAt:effective})),{id:'BPRICE-MANAGED',name:'Managed capacity monthly rate',facilityId:'ALL',service:'MANAGED_INVENTORY',unitSize:'',billingMonths:1,rate:200000,effectiveFrom:effective,effectiveTo:'',status:'ACTIVE',revision:1,updatedAt:effective}],
 policies:bomPolicyTypes.map((name,i)=>({id:'BPOL-'+(i+1),name,description:'Business policy · '+name,rule:name==='Deposit'?'Existing booking demo: deposit equals one undiscounted base month.':name==='Refund'?'Existing Manager demo: unused prepaid days / 30-day period, capped at original payment.':name==='Overdue'?'Existing Manager demo: daily charge equals monthly rental / 30 days.':name==='Access suspension'?'Existing Customer demo: overdue access may be suspended; exact eligibility is not defined.':'Not defined by the current source. Demo draft; backend/business approval required.',effectiveFrom:effective,status:['Deposit','Refund','Overdue'].includes(name)?'ACTIVE':'DRAFT',updatedAt:effective})),
 discounts:[{id:'BDISC-001',name:'Existing 3-month commitment illustration',type:'PROMOTIONAL',valueType:'PERCENTAGE',value:5,conditions:'Existing booking demo: three-month commitment. Future quotes only.',effectiveFrom:effective,effectiveTo:'',status:'ACTIVE',usage:null},{id:'BDISC-002',name:'Loyalty policy draft',type:'LOYALTY',valueType:'UNDEFINED',value:null,conditions:'Eligibility and value are not defined. Demo draft.',effectiveFrom:effective,effectiveTo:'',status:'DRAFT',usage:null},{id:'BDISC-003',name:'Approved fee-waiver policy draft',type:'FEE_WAIVER',valueType:'UNDEFINED',value:null,conditions:'Approval criteria and amount must be supplied by business owners.',effectiveFrom:effective,effectiveTo:'',status:'DRAFT',usage:null}],
 categories:['Documents','Equipment','Business stock','Other'].map((name,i)=>({id:'BCAT-'+(i+1),name,description:'Category already offered by the Customer inventory demo.',allowedStatus:'ALLOWED',handlingNotes:'Demo draft: handling requirements must be confirmed by business owners.',restrictions:'Restrictions not defined by current source.',status:'DRAFT',updatedAt:effective})),
 audit:[{id:'BAUD-INITIAL',actor:'BOM demo seed',action:'DEMO_INITIALIZED',target:'Cross-facility fixture',scope:'ALL',timestamp:effective+'T08:00:00',summary:'Isolated business demo initialized. FAC003 is inactive to demonstrate status filtering.',before:null,after:null}]
};
'''
files['src/lib/bomDemoStore.js']=r'''import {useSyncExternalStore} from 'react';
import {bomSeed,bomToday,bomServices,bomDemoPermissions,bomPolicyTypes} from '@/mocks/bomData';
export const bomDemoEnabled=import.meta.env.VITE_USE_MOCK!=='false';
export const bomStorageKey='VaultSpace_bom_priority4_demo_v1';
const clone=x=>JSON.parse(JSON.stringify(x));
const empty=Object.fromEntries(Object.keys(bomSeed).map(k=>[k,[]]));
let state;try{const stored=JSON.parse(localStorage.getItem(bomStorageKey));state=bomDemoEnabled?{...clone(bomSeed),...(stored||{})}:clone(empty);}catch{state=bomDemoEnabled?clone(bomSeed):clone(empty);}
const listeners=new Set(),notify=()=>listeners.forEach(fn=>fn());
window.addEventListener('storage',e=>{if(e.key===bomStorageKey&&bomDemoEnabled){try{state=e.newValue?{...clone(bomSeed),...JSON.parse(e.newValue)}:clone(bomSeed);notify();}catch{/* Keep last valid demo. */}}});
export function useBomData(){return useSyncExternalStore(fn=>{listeners.add(fn);return()=>listeners.delete(fn)},()=>state);}
export const facilityName=(data,id)=>id==='ALL'?'All facilities':data.facilities.find(f=>f.id===id)?.name||'Unavailable facility';
export const customerName=(data,id)=>data.customers.find(c=>c.id===id)?.name||'Unknown customer';
export const managerName=(data,id)=>data.facilityManagers.find(m=>m.facilityId===id)?.name||'Not assigned';
export const percent=(used,max)=>max?Math.round(used/max*100):0;
export function validPeriod(from,to){return !(from&&to&&from>to);}
export function filteredFacilities(data,filters={}){return data.facilities.filter(f=>(!filters.facility||f.id===filters.facility)&&(!filters.status||f.status===filters.status));}
export function filteredRentals(data,filters={}){const ids=new Set(filteredFacilities(data,filters).map(f=>f.id));return data.rentals.filter(r=>ids.has(r.facilityId)&&validPeriod(filters.from,filters.to)&&(!filters.service||r.service===filters.service)&&(!filters.rentalStatus||r.status===filters.rentalStatus)&&(!filters.from||r.end>=filters.from)&&(!filters.to||r.start<=filters.to)&&(!filters.search||`${r.id} ${customerName(data,r.customerId)}`.toLowerCase().includes(filters.search.toLowerCase())));}
export function filteredPayments(data,filters={}){const ids=new Set(filteredFacilities(data,filters).map(f=>f.id));return data.payments.filter(p=>ids.has(p.facilityId)&&validPeriod(filters.from,filters.to)&&(!filters.from||p.date>=filters.from)&&(!filters.to||p.date<=filters.to)&&(!filters.service||data.rentals.find(r=>r.id===p.rentalId)?.service===filters.service));}
export function facilityMetrics(data,id,filters={}){const rentals=filteredRentals(data,{...filters,facility:id}),payments=filteredPayments(data,{...filters,facility:id}),units=filters.service==='MANAGED_INVENTORY'?[]:data.units.filter(u=>u.facilityId===id),current=data.rentals.filter(r=>r.facilityId===id&&['ACTIVE','OVERDUE'].includes(r.status)&&r.service==='MANAGED_INVENTORY'),managed=filters.service==='SELF_STORAGE'?[]:current;const physical=filters.service==='SELF_STORAGE'?0:data.capacitySnapshots.find(c=>c.facilityId===id)?.operational_capacity_m3||0;const allocated=managed.reduce((s,r)=>s+r.allocated_capacity_m3,0),used=managed.reduce((s,r)=>s+r.used_capacity_m3,0);return {id,units:units.length,occupied:units.filter(u=>u.status==='OCCUPIED').length,available:units.filter(u=>u.status==='AVAILABLE').length,maintenance:units.filter(u=>u.status==='MAINTENANCE').length,physical,allocated,used,unallocated:Math.max(0,physical-allocated),unusedAllocated:Math.max(0,allocated-used),active:rentals.filter(r=>r.status==='ACTIVE').length,overdue:rentals.filter(r=>r.status==='OVERDUE').length,revenue:payments.filter(p=>p.status==='PAID').reduce((s,p)=>s+p.amount,0),alerts:data.alerts.filter(a=>a.facilityId===id&&(!filters.service||a.service===filters.service)&&a.status!=='RESOLVED')};}
export function totalMetrics(data,filters={}){return filteredFacilities(data,filters).reduce((sum,f)=>{const m=facilityMetrics(data,f.id,filters);for(const k of ['units','occupied','available','maintenance','physical','allocated','used','unallocated','unusedAllocated','active','overdue','revenue'])sum[k]+=m[k];sum.alerts+=m.alerts.length;return sum;},{units:0,occupied:0,available:0,maintenance:0,physical:0,allocated:0,used:0,unallocated:0,unusedAllocated:0,active:0,overdue:0,revenue:0,alerts:0});}
export function auditRecords(data){return bomDemoEnabled&&bomDemoPermissions.viewAudit?data.audit:[];}
function change(fn){if(!bomDemoEnabled||!bomDemoPermissions.manageBusiness)throw Error('BOM APIs/authorization are not connected. Demo changes are unavailable.');const next=clone(state);fn(next);localStorage.setItem(bomStorageKey,JSON.stringify(next));state=next;notify();}
function record(data,action,target,scope,before,after,reason){data.audit.unshift({id:'BAUD-'+crypto.randomUUID(),actor:'Business Operations demo operator',action,target,scope,timestamp:new Date().toISOString(),summary:reason,before:clone(before),after:clone(after)});}
function text(value,label){if(typeof value!=='string'||!value.trim())throw Error(label+' is required.');return value.trim();}
function get(data,collection,id){const row=data[collection]?.find(r=>r.id===id);if(!row)throw Error('Business record unavailable.');return row;}
function confirmation(confirmed,reason){if(confirmed!==true)throw Error('Explicit confirmation is required.');return text(reason,'Change reason');}
function dates(from,to){if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!Number.isFinite(Date.parse(from))||new Date(from).toISOString().slice(0,10)!==from)throw Error('A valid effective date is required.');if(from<bomToday)throw Error('Changes may take effect today or in the future only.');if(to&&(!/^\d{4}-\d{2}-\d{2}$/.test(to)||!Number.isFinite(Date.parse(to))||new Date(to).toISOString().slice(0,10)!==to||to<from))throw Error('Effective end must be a valid date on or after the start.');}
function status(value,allowed){if(!allowed.includes(value))throw Error('Unsupported business status.');return value;}
export function saveFacility(id,values,{confirmed,reason}){return change(data=>{const why=confirmation(confirmed,reason),previous=id?get(data,'facilities',id):null;const row={id:previous?.id||'BFAC-'+crypto.randomUUID(),name:text(values.name,'Facility name'),district:text(values.district,'District/location'),address:text(values.address,'Address'),openingHours:text(values.openingHours,'Opening hours'),status:status(values.status,['ACTIVE','INACTIVE'])};if(data.facilities.some(f=>f.id!==id&&f.name.toLowerCase()===row.name.toLowerCase()))throw Error('A facility with this name already exists.');if(previous)data.facilities[data.facilities.indexOf(previous)]=row;else data.facilities.push(row);record(data,previous?'FACILITY_UPDATED':'FACILITY_CREATED',row.id,row.id,previous,row,why);});}
export function setFacilityStatus(id,nextStatus,{confirmed,reason}){change(data=>{const why=confirmation(confirmed,reason),row=get(data,'facilities',id),before=clone(row);status(nextStatus,['ACTIVE','INACTIVE']);if(row.status===nextStatus)throw Error('The facility already has this status.');row.status=nextStatus;record(data,'FACILITY_STATUS_CHANGED',id,id,before,row,why+' Existing rentals preserved.');});}
export function canReserve(data,id){return data.facilities.find(f=>f.id===id)?.status==='ACTIVE';}
export function savePricing(id,values,{confirmed,reason}){change(data=>{const why=confirmation(confirmed,reason),previous=id?get(data,'pricing',id):null;status(values.service,bomServices);status(values.status,['ACTIVE','INACTIVE']);if(values.facilityId!=='ALL')get(data,'facilities',values.facilityId);const months=Number(values.billingMonths),rate=Number(values.rate);if(![1,3,6,12].includes(months)||!Number.isFinite(rate)||rate<=0)throw Error('A supported billing duration and positive rate are required.');const size=values.service==='SELF_STORAGE'?status(values.unitSize,['Small','Medium','Large']):'';dates(values.effectiveFrom,values.effectiveTo);const row={id:previous?.id||'BPRICE-'+crypto.randomUUID(),name:text(values.name,'Rule name'),facilityId:values.facilityId,service:values.service,unitSize:size,billingMonths:months,rate,effectiveFrom:values.effectiveFrom,effectiveTo:values.effectiveTo||'',status:values.status,revision:(previous?.revision||0)+1,updatedAt:new Date().toISOString()};const overlap=data.pricing.some(p=>p.id!==id&&p.status==='ACTIVE'&&row.status==='ACTIVE'&&p.service===row.service&&p.unitSize===row.unitSize&&p.billingMonths===row.billingMonths&&(p.facilityId==='ALL'||row.facilityId==='ALL'||p.facilityId===row.facilityId)&&p.effectiveFrom<=(row.effectiveTo||'9999-12-31')&&row.effectiveFrom<=(p.effectiveTo||'9999-12-31'));if(overlap)throw Error('An active pricing rule overlaps this service, unit size, billing period, scope and effective period.');if(previous)data.pricing[data.pricing.indexOf(previous)]=row;else data.pricing.push(row);record(data,previous?'PRICING_REVISED':'PRICING_CREATED',row.id,row.facilityId,previous,row,why+' Future pricing only; contract/payment snapshots unchanged.');});}
export function savePolicy(id,values,{confirmed,reason}){change(data=>{const why=confirmation(confirmed,reason),previous=get(data,'policies',id);if(!bomPolicyTypes.includes(previous.name))throw Error('Unsupported policy.');dates(values.effectiveFrom,'');const row={...previous,description:text(values.description,'Description'),rule:text(values.rule,'Policy rule'),effectiveFrom:values.effectiveFrom,status:status(values.status,['ACTIVE','INACTIVE','DRAFT']),updatedAt:new Date().toISOString()};if(row.status==='ACTIVE'&&/not defined|not confirmed|demo draft/i.test(row.rule))throw Error('Define the rule before activating a draft policy.');data.policies[data.policies.indexOf(previous)]=row;record(data,'POLICY_REVISED',id,'ALL',previous,row,why);});}
export function saveDiscount(id,values,{confirmed,reason}){change(data=>{const why=confirmation(confirmed,reason),previous=id?get(data,'discounts',id):null;dates(values.effectiveFrom,values.effectiveTo);const type=status(values.type,['PROMOTIONAL','LOYALTY','FEE_WAIVER']),valueType=status(values.valueType,['PERCENTAGE','FIXED','UNDEFINED']),value=valueType==='UNDEFINED'?null:Number(values.value),active=status(values.status,['ACTIVE','INACTIVE','DRAFT']);if(valueType!=='UNDEFINED'&&(!Number.isFinite(value)||value<=0||(valueType==='PERCENTAGE'&&value>100)))throw Error('Use a positive fixed amount or a percentage between 0 and 100.');if(active==='ACTIVE'&&valueType==='UNDEFINED')throw Error('A discount value is required before activation.');const row={id:previous?.id||'BDISC-'+crypto.randomUUID(),name:text(values.name,'Policy name'),type,valueType,value,conditions:text(values.conditions,'Conditions'),effectiveFrom:values.effectiveFrom,effectiveTo:values.effectiveTo||'',status:active,usage:previous?.usage??null,updatedAt:new Date().toISOString()};if(previous)data.discounts[data.discounts.indexOf(previous)]=row;else data.discounts.push(row);record(data,previous?'DISCOUNT_REVISED':'DISCOUNT_CREATED',row.id,'ALL',previous,row,why+' No payment mutation.');});}
export function saveCategory(id,values,{confirmed,reason}){change(data=>{const why=confirmation(confirmed,reason),previous=id?get(data,'categories',id):null;const row={id:previous?.id||'BCAT-'+crypto.randomUUID(),name:text(values.name,'Category name'),description:text(values.description,'Description'),allowedStatus:status(values.allowedStatus,['ALLOWED','PROHIBITED']),handlingNotes:text(values.handlingNotes,'Handling notes'),restrictions:text(values.restrictions,'Restrictions'),status:status(values.status,['ACTIVE','INACTIVE','DRAFT']),updatedAt:new Date().toISOString()};if(data.categories.some(c=>c.id!==id&&c.name.toLowerCase()===row.name.toLowerCase()))throw Error('Category name already exists.');if(previous)data.categories[data.categories.indexOf(previous)]=row;else data.categories.push(row);record(data,previous?'CATEGORY_REVISED':'CATEGORY_CREATED',row.id,'MANAGED_INVENTORY',previous,row,why);});}
'''
for name,body in files.items():
 p=Path(name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body,encoding='utf-8')
